using System.Net;using System.Net.Http.Headers;
namespace SmartERP.Sales.API.Authentication;
public interface ICompanyAccessValidator{Task<bool>HasAccessAsync(int companyId,CancellationToken token=default);}
public sealed class CompanyAccessValidator(IHttpClientFactory factory,IHttpContextAccessor accessor):ICompanyAccessValidator{public async Task<bool>HasAccessAsync(int id,CancellationToken token=default){var authorization=accessor.HttpContext?.Request.Headers.Authorization.FirstOrDefault();if(string.IsNullOrWhiteSpace(authorization))return false;using var request=new HttpRequestMessage(HttpMethod.Get,$"api/companies/{id}");request.Headers.Authorization=AuthenticationHeaderValue.Parse(authorization);using var response=await factory.CreateClient("OrganizationAccess").SendAsync(request,token);return response.StatusCode==HttpStatusCode.OK;}}
public sealed class CompanyAccessFilter(ICompanyAccessValidator validator,IRequestContext context):IEndpointFilter{public async ValueTask<object?>InvokeAsync(EndpointFilterInvocationContext invocation,EndpointFilterDelegate next)=>await validator.HasAccessAsync(context.CompanyId,invocation.HttpContext.RequestAborted)?await next(invocation):Results.Forbid();}
